{"filePath":"/workspace/src/koruapi/dashboard_logs.py","newString":"def _stream_new_lines(path: Path, offset: int, parser, levels: set[str], events_sent: int, json_module) -> int:
    """Stream new lines from a log file, yielding SSE events.
    Returns updated events_sent count.
    """
    try:
        current_size = path.stat().st_size
        if current_size < offset:
            offset = 0  # file was truncated/rotated
        if current_size > offset:
            with path.open("r", encoding="utf-8", errors="ignore") as f:
                f.seek(offset)
                for line in f:
                    entry = parser(line)
                    if entry and entry["level"] in levels:
                        yield f"data: {json_module.dumps(entry)}\n\n"
                        events_sent += 1
                offset = f.tell()
    except OSError:
        pass
    return events_sent, offset

def _update_offset(path: Path, offset: int) -> int:
    try:
        return path.stat().st_size
    except OSError:
        return offset
